package com.example.bikerental; import org.springframework.data.jpa.repository.JpaRepository; import java.util.List; public interface WaitlistEntryRepository extends JpaRepository<WaitlistEntry,Long>{ List<WaitlistEntry> findByUsernameOrderByCreatedAtDesc(String username); List<WaitlistEntry> findByBikeIdAndNotifiedFalse(Long bikeId); boolean existsByUsernameAndBikeIdAndNotifiedFalse(String username,Long bikeId); }